{
  "findings": [
    {
      "check_id": "CKV_AZURE_130",
      "title": "Ensure that PostgreSQL server enables infrastructure encryption",
      "resource": "azurerm_postgresql_server.example",
      "severity": "MEDIUM",
      "explanation": "The PostgreSQL server does not explicitly enable infrastructure encryption, which ensures data at rest is encrypted using a second layer of encryption."
    },
    {
      "check_id": "CKV2_AZURE_42",
      "title": "Ensure Azure PostgreSQL server is configured with private endpoint",
      "resource": "azurerm_postgresql_server.example",
      "severity": "MEDIUM",
      "explanation": "The PostgreSQL server is not configured with a private endpoint, which could expose it to public network access."
    },
    {
      "check_id": "CKV_AZURE_68",
      "title": "Ensure that PostgreSQL server disables public network access",
      "resource": "azurerm_postgresql_server.example",
      "severity": "MEDIUM",
      "explanation": "The PostgreSQL server does not explicitly disable public network access, which increases the risk of unauthorized access."
    },
    {
      "check_id": "CKV_AZURE_102",
      "title": "Ensure that PostgreSQL server enables geo-redundant backups",
      "resource": "azurerm_postgresql_server.example",
      "severity": "MEDIUM",
      "explanation": "The PostgreSQL server does not enable geo-redundant backups, which could lead to data loss in case of a regional failure."
    },
    {
      "check_id": "CKV_AZURE_128",
      "title": "Ensure that PostgreSQL server enables Threat detection policy",
      "resource": "azurerm_postgresql_server.example",
      "severity": "MEDIUM",
      "explanation": "The PostgreSQL server does not enable a Threat detection policy, which helps detect anomalous activities indicating potential security threats."
    }
  ],
  "patched_code": "resource \"azurerm_postgresql_configuration\" \"negative1\" {\n  name                = \"log_retention_days\"\n  resource_group_name = azurerm_resource_group.example.name\n  server_name         = azurerm_postgresql_server.example.name\n  value               = 5\n}\n\nresource \"azurerm_postgresql_server\" \"example\" {\n  name                = \"example-server\"\n  location            = azurerm_resource_group.example.location\n  resource_group_name = azurerm_resource_group.example.name\n  sku_name            = \"GP_Gen5_2\"\n  storage_mb          = 5120\n  backup_retention_days = 7\n  geo_redundant_backup_enabled = true\n  administrator_login = \"adminuser\"\n  administrator_login_password = \"securepassword123\"\n  version             = \"11\"\n  public_network_access_enabled = false\n  infrastructure_encryption_enabled = true\n\n  threat_detection_policy {\n    enabled = true\n    email_account_admins = true\n    email_addresses = [\"security@example.com\"]\n  }\n}\n\nresource \"azurerm_private_endpoint\" \"example\" {\n  name                = \"example-private-endpoint\"\n  location            = azurerm_resource_group.example.location\n  resource_group_name = azurerm_resource_group.example.name\n  subnet_id           = azurerm_subnet.example.id\n\n  private_service_connection {\n    name                           = \"example-connection\"\n    private_connection_resource_id = azurerm_postgresql_server.example.id\n    is_manual_connection           = false\n  }\n}",
  "fix_summary": "Added a PostgreSQL server resource with infrastructure encryption, private endpoint, disabled public network access, geo-redundant backups, and a Threat detection policy to address the identified misconfigurations."
}
